private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get();
        if (b >= 0) {
            sb.append((char) b);
        } else {
            int leadingZeros = 5 - (Integer.numberOfLeadingZeros(b) >>> 3);
            StringBuilder c = new StringBuilder();
            do {
                c.append((char) ((b & 0x3F) | 0x80));
                b = bb.get();
            } while ((b & 0xC0) == 0x80);
            c.append((char) ((b & (0x7F >>> leadingZeros)) | (0xFFL << (8 - leadingZeros))));
            try {
                sb.append(c.reverse().toString(), 1, c.length());
            } catch (Exception e) {
                return -1;
            }
        }
        i++;
    }
    return i;
}

