private void pop(final String descriptor) {
    int numToPop = 0;

    if (descriptor.startsWith("(")) {
        int balance = 1;
        int i = 1;
        while (balance != 0) {
            char c = descriptor.charAt(i);
            if (c == '(') balance++;
            if (c == ')') balance--;
            if (balance != 0) numToPop++;
            i++;
        }
    } else {
        numToPop = 1;
